CompositionLocalProvider(LocalConfiguration provides locale) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Heading)
        MonarchText(text = {{description}})
        MonarchSegmentedControl(
            modifier = Modifier.horizontalScroll(rememberScrollState()),
            options = periods,
            selectedIndex = periods.indexOf(period),
            onSelect = { period = periods[it] },
        )
        MonarchButton(
            text = if (editing) "Done" else {{arrange}},
            onClick = { editing = !editing },
            size = MonarchButtonSize.Sm,
        )
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchStatCard(label = {{kpis.0.label}}, value = {{kpis.0.value|double}}, modifier = Modifier.weight(1f).testTag({{kpis.0.id}}))
            MonarchStatCard(label = {{kpis.1.label}}, value = {{kpis.1.value|double}}, modifier = Modifier.weight(1f).testTag({{kpis.1.id}}))
            MonarchStatCard(
                label = {{kpis.2.label}},
                value = {{kpis.2.value|double}},
                modifier = Modifier.weight(1f).testTag({{kpis.2.id}}),
                change = MonarchMetricChange({{kpis.2.change.value|double}}, comparison = {{kpis.2.change.comparison}}),
            )
        }
        MonarchInsightStrip(
            insights = listOf(
                MonarchInsight(
                    id = {{insights.0.id}},
                    title = {{insights.0.title}},
                    why = {{insights.0.why}},
                    origin = MonarchInsightOrigin.{{insights.0.origin|pascal}},
                    tone = {{insights.0.severity|tone}},
                ),
            ),
            title = "Insights",
        )
        MonarchDashboardGrid(
            items = tiles,
            key = { it },
            itemLabel = { it },
            layout = layout,
            onLayoutChange = { layout = it },
            editing = editing,
            modifier = Modifier.fillMaxSize(),
        ) { tile ->
            when (tile) {
                {{today.title}} -> MonarchWidget(title = tile, description = {{today.date}}) {
                    MonarchText(text = {{today.heading}}, style = MonarchTextStyle.BodyStrong)
                    tasks.forEach { (id, title) ->
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            MonarchCheckboxRow(
                                checked = id in done,
                                onCheckedChange = { on -> done = if (on) done + id else done - id },
                                label = title,
                                modifier = Modifier.weight(1f),
                            )
                            if (id == {{today.overdue.0}}) MonarchBadge(text = "Overdue", tone = MonarchTone.Danger)
                        }
                    }
                }
                {{assigned.title}} -> MonarchWidget(title = tile) {
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = {{assigned.rows.0.label}}, modifier = Modifier.weight(1f)); MonarchBadge(text = {{assigned.rows.0.value}}, tone = {{assigned.rows.0.tone|tone}}) }
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = {{assigned.rows.1.label}}, modifier = Modifier.weight(1f)); MonarchBadge(text = {{assigned.rows.1.value}}, tone = {{assigned.rows.1.tone|tone}}) }
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = {{assigned.rows.2.label}}, modifier = Modifier.weight(1f)); MonarchBadge(text = {{assigned.rows.2.value}}, tone = {{assigned.rows.2.tone|tone}}) }
                }
                {{dueSoon.title}} -> MonarchWidget(title = tile) {
                    row({{dueSoon.rows.0.label}}, {{dueSoon.rows.0.value}})
                    row({{dueSoon.rows.1.label}}, {{dueSoon.rows.1.value}})
                    row({{dueSoon.rows.2.label}}, {{dueSoon.rows.2.value}})
                }
                {{progress.title}} -> MonarchWidget(title = tile) {
                    row({{progress.goals.0.label}}, {{progress.goals.0.value}}.toString() + "%")
                    MonarchProgress(progress = {{progress.goals.0.value}} / 100f, label = {{progress.goals.0.label}})
                    row({{progress.goals.1.label}}, {{progress.goals.1.value}}.toString() + "%")
                    MonarchProgress(progress = {{progress.goals.1.value}} / 100f, label = {{progress.goals.1.label}})
                }
                {{announcements.title}} -> MonarchWidget(title = tile) {
                    MonarchText(text = {{announcements.items.0.term}}, style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = {{announcements.items.0.body}})
                }
                {{team.title}} -> MonarchWidget(title = tile) {
                    row({{team.rows.0.label}}, {{team.rows.0.value}})
                    row({{team.rows.1.label}}, {{team.rows.1.value}})
                }
                else -> MonarchWidget(title = tile) {
                    MonarchActivityTimeline(
                        events = events,
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 320.dp),
                        groupByDay = false,
                        density = MonarchActivityTimelineDensity.Compact,
                        now = now,
                        timeZone = {{timeZone}},
                    )
                }
            }
        }
    }
}

examples.setupTemplate:
var period by rememberSaveable { mutableStateOf({{period}}) }
val periods = listOf({{periods.0}}, {{periods.1}}, {{periods.2}}, {{periods.3}}, {{periods.4}})
var editing by remember { mutableStateOf(false) }
var layout by remember { mutableStateOf(emptyList<String>()) }
var done by rememberSaveable { mutableStateOf(setOf({{today.done.0}})) }
val tiles = listOf({{today.title}}, {{assigned.title}}, {{dueSoon.title}}, {{progress.title}}, {{announcements.title}}, {{team.title}}, {{activity.title}})
val now = {{activity.now|millis}}
val tasks = listOf(
    {{today.tasks.0.id}} to {{today.tasks.0.title}},
    {{today.tasks.1.id}} to {{today.tasks.1.title}},
    {{today.tasks.2.id}} to {{today.tasks.2.title}},
)
val row: @Composable (String, String) -> Unit = { label, value ->
    Row(verticalAlignment = Alignment.CenterVertically) {
        MonarchText(text = label, modifier = Modifier.weight(1f))
        MonarchText(text = value)
    }
}
val events = listOf(
    MonarchActivityTimelineEvent(
        id = {{activity.events.0.id}},
        verb = {{activity.events.0.verb}},
        time = {{activity.events.0.time|millis}},
        actor = MonarchActivityTimelineActor({{activity.events.0.actor}}),
        target = {{activity.events.0.object}},
    ),
    MonarchActivityTimelineEvent(
        id = {{activity.events.1.id}},
        verb = {{activity.events.1.verb}},
        time = {{activity.events.1.time|millis}},
        actor = MonarchActivityTimelineActor({{activity.events.1.actor}}),
        target = {{activity.events.1.object}},
    ),
)
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

