CompositionLocalProvider(LocalConfiguration provides locale) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
        MonarchText(text = "My work", style = MonarchTextStyle.Heading)
        MonarchText(text = "Priya Raman · Product team")
        MonarchSegmentedControl(
            modifier = Modifier.horizontalScroll(rememberScrollState()),
            options = periods,
            selectedIndex = periods.indexOf(period),
            onSelect = { period = periods[it] },
        )
        MonarchButton(
            text = if (editing) "Done" else "Arrange",
            onClick = { editing = !editing },
            size = MonarchButtonSize.Sm,
        )
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchStatCard(label = "Assigned to you", value = 12.0, modifier = Modifier.weight(1f).testTag("assigned"))
            MonarchStatCard(label = "Due this week", value = 4.0, modifier = Modifier.weight(1f).testTag("due"))
            MonarchStatCard(
                label = "Done this month",
                value = 27.0,
                modifier = Modifier.weight(1f).testTag("done"),
                change = MonarchMetricChange(0.17, comparison = "vs last month"),
            )
        }
        MonarchInsightStrip(
            insights = listOf(
                MonarchInsight(
                    id = "blocked",
                    title = "Two of your tasks are blocked",
                    why = "Both wait on the design review on Wednesday.",
                    origin = MonarchInsightOrigin.Rule,
                    tone = MonarchTone.Info,
                ),
            ),
            title = "Insights",
        )
        MonarchDashboardGrid(
            items = tiles,
            key = { it },
            itemLabel = { it },
            layout = layout,
            onLayoutChange = { layout = it },
            editing = editing,
            modifier = Modifier.fillMaxSize(),
        ) { tile ->
            when (tile) {
                "Today" -> MonarchWidget(title = tile, description = "Monday 15 June") {
                    MonarchText(text = "Due today", style = MonarchTextStyle.BodyStrong)
                    tasks.forEach { (id, title) ->
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            MonarchCheckboxRow(
                                checked = id in done,
                                onCheckedChange = { on -> done = if (on) done + id else done - id },
                                label = title,
                                modifier = Modifier.weight(1f),
                            )
                            if (id == "t1") MonarchBadge(text = "Overdue", tone = MonarchTone.Danger)
                        }
                    }
                }
                "Assigned to you" -> MonarchWidget(title = tile) {
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = "In progress", modifier = Modifier.weight(1f)); MonarchBadge(text = "5", tone = MonarchTone.Info) }
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = "In review", modifier = Modifier.weight(1f)); MonarchBadge(text = "3", tone = MonarchTone.Warning) }
                    Row(verticalAlignment = Alignment.CenterVertically) { MonarchText(text = "To do", modifier = Modifier.weight(1f)); MonarchBadge(text = "4", tone = MonarchTone.Neutral) }
                }
                "Due soon" -> MonarchWidget(title = tile) {
                    row("Update the pricing page", "Wed 17 Jun")
                    row("Plan the June release", "Thu 18 Jun")
                    row("Write the onboarding guide", "Fri 19 Jun")
                }
                "Progress" -> MonarchWidget(title = tile) {
                    row("Q2 goal: ship the new checkout", 70.toString() + "%")
                    MonarchProgress(progress = 70 / 100f, label = "Q2 goal: ship the new checkout")
                    row("Cut first reply time to one hour", 45.toString() + "%")
                    MonarchProgress(progress = 45 / 100f, label = "Cut first reply time to one hour")
                }
                "Announcements" -> MonarchWidget(title = tile) {
                    MonarchText(text = "Office closed on Friday 19 June", style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = "Everyone works from home that day.")
                }
                "Your team" -> MonarchWidget(title = tile) {
                    row("Leave request, Jonas Weber", "22 to 26 Jun")
                    row("Expense claim, Amara Okafor", "£86.40")
                }
                else -> MonarchWidget(title = tile) {
                    MonarchActivityTimeline(
                        events = events,
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 320.dp),
                        groupByDay = false,
                        density = MonarchActivityTimelineDensity.Compact,
                        now = now,
                        timeZone = "Europe/London",
                    )
                }
            }
        }
    }
}
